import Foundation
import UIKit
import WebKit

// MARK: - Input Models

struct InputFocusPayload: Codable {
    let action: String
    let x: Double
    let y: Double
    let width: Double
    let height: Double
    let fontSize: Double
    let lineHeight: Double
    let currentText: String
    let paddingTop: Double
    let paddingLeft: Double
    let paddingRight: Double
    let paddingBottom: Double
    let selectionStart: Int?
    let selectionEnd: Int?
    let placeholder: String?
    let keyboardType: String?
    let returnKey: String?
    let autocorrect: Bool?
    let autocapitalize: String?

    var frame: CGRect {
        CGRect(x: x, y: y, width: max(width, 40), height: max(height, 40))
    }

    var resolvedReturnKeyType: UIReturnKeyType {
        switch returnKey?.lowercased() {
        case "send":    return .send
        case "go":      return .go
        case "search":  return .search
        case "next":    return .next
        case "done":    return .done
        default:        return .send
        }
    }

    var resolvedKeyboardType: UIKeyboardType {
        switch keyboardType?.lowercased() {
        case "email":    return .emailAddress
        case "number":   return .numberPad
        case "phone":    return .phonePad
        case "url":      return .URL
        case "decimal":  return .decimalPad
        default:         return .default
        }
    }

    var resolvedAutocapitalizationType: UITextAutocapitalizationType {
        switch autocapitalize?.lowercased() {
        case "none", "off": return .none
        case "words":       return .words
        case "characters":  return .allCharacters
        default:            return .sentences
        }
    }
}

// MARK: - InputBridgeDelegate

protocol InputBridgeDelegate: AnyObject {
    func inputBridge(_ bridge: InputBridge, requestFocusWith payload: InputFocusPayload)
    func inputBridge(_ bridge: InputBridge, requestDismiss payload: InputFocusPayload?)
    func inputBridgeDidEncounterError(_ bridge: InputBridge, error: Error)
}

// MARK: - InputBridge

final class InputBridge: NSObject, WKScriptMessageHandler {

    // MARK: - Properties

    weak var delegate: InputBridgeDelegate?

    private let decoder = JSONDecoder()
    private var lastKnownPayload: InputFocusPayload?

    // MARK: - WKScriptMessageHandler

    func userContentController(
        _ userContentController: WKUserContentController,
        didReceive message: WKScriptMessage
    ) {
        guard message.name == "inputBridge" else { return }

        let payload: InputFocusPayload

        if let dict = message.body as? [String: Any],
           let data = try? JSONSerialization.data(withJSONObject: dict),
           let decoded = try? decoder.decode(InputFocusPayload.self, from: data) {
            payload = decoded
        } else if let jsonStr = message.body as? String,
                  let data = jsonStr.data(using: .utf8),
                  let decoded = try? decoder.decode(InputFocusPayload.self, from: data) {
            payload = decoded
        } else {
            let err = NSError(
                domain: "InputBridge",
                code: 422,
                userInfo: [NSLocalizedDescriptionKey: "Cannot decode inputBridge message: \(type(of: message.body))"]
            )
            print("[InputBridge] Decode error: \(err)")
            DispatchQueue.main.async { [weak self] in
                guard let self = self else { return }
                self.delegate?.inputBridgeDidEncounterError(self, error: err)
            }
            return
        }

        DispatchQueue.main.async { [weak self] in
            guard let self = self else { return }
            self.lastKnownPayload = payload
            switch payload.action {
            case "focus":
                self.delegate?.inputBridge(self, requestFocusWith: payload)
            case "blur", "dismiss":
                self.delegate?.inputBridge(self, requestDismiss: payload)
            case "update":
                // Re-focus with updated geometry (e.g. after layout shift)
                self.delegate?.inputBridge(self, requestFocusWith: payload)
            default:
                print("[InputBridge] Unknown action: \(payload.action)")
            }
        }
    }
}

// MARK: - NativeInputOverlay

/// Manages the native UITextView and placeholder label overlay on top of the web view.
final class NativeInputOverlay: NSObject {

    // MARK: - Public Properties

    var onTextChange: ((String) -> Void)?
    var onSubmit: ((String) -> Void)?
    var onDismiss: (() -> Void)?
    var onHeightChange: ((CGFloat) -> Void)?

    private(set) var isPresented: Bool = false
    private(set) var currentText: String = ""

    // MARK: - Private Properties

    private weak var containerView: UIView?
    private weak var webView: WKWebView?

    private var textView: UITextView?
    private var placeholderLabel: UILabel?

    private var isDismissing = false
    private var keyboardHeight: CGFloat = 0

    private let maxHeight: CGFloat = 176
    private let minHeight: CGFloat = 40

    // MARK: - Init

    init(containerView: UIView, webView: WKWebView) {
        self.containerView = containerView
        self.webView = webView
        super.init()
        registerKeyboardObservers()
    }

    deinit {
        NotificationCenter.default.removeObserver(self)
    }

    // MARK: - Present / Dismiss

    func present(with payload: InputFocusPayload) {
        guard !isDismissing else { return }

        // Dismiss any existing overlay first without animation
        dismissInternal(animated: false, syncText: false, fireCallback: false)

        guard let container = containerView else { return }

        let frame = payload.frame
        let tv = UITextView(frame: frame)
        tv.backgroundColor = .clear
        tv.textColor = UIColor(white: 0.96, alpha: 1.0)
        tv.font = UIFont.systemFont(ofSize: CGFloat(payload.fontSize), weight: .regular)
        tv.keyboardAppearance = .dark
        tv.returnKeyType = payload.resolvedReturnKeyType
        tv.keyboardType = payload.resolvedKeyboardType
        tv.autocorrectionType = payload.autocorrect == false ? .no : .default
        tv.autocapitalizationType = payload.resolvedAutocapitalizationType
        tv.spellCheckingType = .default
        tv.isScrollEnabled = false
        tv.textContainer.lineFragmentPadding = 0
        tv.textContainerInset = UIEdgeInsets(
            top:    CGFloat(payload.paddingTop),
            left:   CGFloat(payload.paddingLeft),
            bottom: CGFloat(payload.paddingBottom),
            right:  CGFloat(payload.paddingRight)
        )
        tv.text = payload.currentText
        tv.delegate = self
        tv.layer.zPosition = 9000
        tv.isUserInteractionEnabled = true
        tv.dataDetectorTypes = []

        // Restore selection position if provided
        if let start = payload.selectionStart, let end = payload.selectionEnd {
            let nsRange = NSRange(location: min(start, tv.text.count),
                                  length: max(0, min(end, tv.text.count) - min(start, tv.text.count)))
            if let textRange = Range(nsRange, in: tv.text) {
                let uiRange = tv.textRange(
                    from: tv.position(from: tv.beginningOfDocument, offset: start) ?? tv.beginningOfDocument,
                    to:   tv.position(from: tv.beginningOfDocument, offset: end) ?? tv.endOfDocument
                )
                if let uiRange = uiRange {
                    tv.selectedTextRange = uiRange
                }
                _ = textRange // suppress warning
            }
        } else {
            // Move cursor to end
            tv.selectedRange = NSRange(location: tv.text.count, length: 0)
        }

        // Placeholder label
        let placeholder = UILabel()
        placeholder.text = payload.placeholder ?? "Üzenet"
        placeholder.textColor = UIColor(white: 1.0, alpha: 0.28)
        placeholder.font = tv.font
        placeholder.backgroundColor = .clear
        placeholder.isUserInteractionEnabled = false
        placeholder.layer.zPosition = 8999
        placeholder.frame = CGRect(
            x: frame.origin.x + CGFloat(payload.paddingLeft) + 5,
            y: frame.origin.y + CGFloat(payload.paddingTop),
            width: frame.width - CGFloat(payload.paddingLeft) - CGFloat(payload.paddingRight) - 5,
            height: frame.height - CGFloat(payload.paddingTop) - CGFloat(payload.paddingBottom)
        )
        placeholder.isHidden = !payload.currentText.isEmpty

        container.isUserInteractionEnabled = true
        container.addSubview(placeholder)
        container.addSubview(tv)

        self.textView = tv
        self.placeholderLabel = placeholder
        self.currentText = payload.currentText
        self.isPresented = true

        tv.becomeFirstResponder()
    }

    func dismiss(syncText: Bool = true) {
        dismissInternal(animated: true, syncText: syncText, fireCallback: true)
    }

    private func dismissInternal(animated: Bool, syncText: Bool, fireCallback: Bool) {
        guard !isDismissing else { return }
        isDismissing = true
        defer { isDismissing = false }

        if syncText, let tv = textView {
            currentText = tv.text ?? ""
        }

        textView?.resignFirstResponder()
        textView?.removeFromSuperview()
        placeholderLabel?.removeFromSuperview()
        textView = nil
        placeholderLabel = nil
        containerView?.isUserInteractionEnabled = false
        isPresented = false
        keyboardHeight = 0

        if fireCallback { onDismiss?() }
    }

    // MARK: - Geometry Update

    func updateFrame(_ frame: CGRect) {
        guard let tv = textView, let pl = placeholderLabel else { return }
        UIView.performWithoutAnimation {
            tv.frame = frame
            pl.frame = CGRect(
                x: frame.origin.x + tv.textContainerInset.left + 5,
                y: frame.origin.y + tv.textContainerInset.top,
                width: frame.width - tv.textContainerInset.left - tv.textContainerInset.right - 5,
                height: frame.height - tv.textContainerInset.top - tv.textContainerInset.bottom
            )
        }
    }

    func syncText(_ text: String) {
        currentText = text
        textView?.text = text
        placeholderLabel?.isHidden = !text.isEmpty
        reflowHeight()
    }

    // MARK: - Keyboard

    func applyKeyboardOffset(_ height: CGFloat, duration: TimeInterval, curve: UIView.AnimationOptions) {
        guard let tv = textView, let pl = placeholderLabel else { return }
        keyboardHeight = height
        UIView.animate(withDuration: duration, delay: 0, options: curve) {
            tv.transform = CGAffineTransform(translationX: 0, y: -height)
            pl.transform = CGAffineTransform(translationX: 0, y: -height)
        }
    }

    func resetKeyboardOffset(duration: TimeInterval, curve: UIView.AnimationOptions) {
        guard let tv = textView, let pl = placeholderLabel else { return }
        keyboardHeight = 0
        UIView.animate(withDuration: duration, delay: 0, options: curve) {
            tv.transform = .identity
            pl.transform = .identity
        }
    }

    // MARK: - Private

    private func reflowHeight() {
        guard let tv = textView else { return }
        let insets = tv.textContainerInset
        let fittingSize = tv.sizeThatFits(CGSize(width: tv.bounds.width, height: .greatestFiniteMagnitude))
        let newHeight = max(minHeight, min(maxHeight, fittingSize.height + insets.top + insets.bottom))
        if abs(tv.frame.height - newHeight) > 1 {
            var f = tv.frame
            f.origin.y += f.height - newHeight
            f.size.height = newHeight
            UIView.animate(withDuration: 0.15, delay: 0, options: .curveEaseInOut) {
                tv.frame = f
                self.placeholderLabel?.frame.origin.y = f.origin.y + insets.top
            }
            onHeightChange?(newHeight)
        }
    }

    private func registerKeyboardObservers() {
        NotificationCenter.default.addObserver(
            self, selector: #selector(keyboardWillShow(_:)),
            name: UIResponder.keyboardWillShowNotification, object: nil
        )
        NotificationCenter.default.addObserver(
            self, selector: #selector(keyboardWillHide(_:)),
            name: UIResponder.keyboardWillHideNotification, object: nil
        )
    }

    @objc private func keyboardWillShow(_ n: Notification) {
        guard let info = n.userInfo,
              let kbFrame = info[UIResponder.keyboardFrameEndUserInfoKey] as? CGRect,
              let duration = info[UIResponder.keyboardAnimationDurationUserInfoKey] as? Double,
              let curveRaw = info[UIResponder.keyboardAnimationCurveUserInfoKey] as? UInt else { return }
        let safeInset = containerView?.safeAreaInsets.bottom ?? 0
        let height = max(0, kbFrame.height - safeInset)
        let curve = UIView.AnimationOptions(rawValue: curveRaw << 16)
        applyKeyboardOffset(height, duration: duration, curve: curve)
        webView?.evaluateJavaScript(
            "window.__nativeBridge && window.__nativeBridge.onKeyboardShow(\(kbFrame.height));",
            completionHandler: nil
        )
    }

    @objc private func keyboardWillHide(_ n: Notification) {
        guard let info = n.userInfo,
              let duration = info[UIResponder.keyboardAnimationDurationUserInfoKey] as? Double,
              let curveRaw = info[UIResponder.keyboardAnimationCurveUserInfoKey] as? UInt else { return }
        let curve = UIView.AnimationOptions(rawValue: curveRaw << 16)
        resetKeyboardOffset(duration: duration, curve: curve)
        webView?.evaluateJavaScript(
            "window.__nativeBridge && window.__nativeBridge.onKeyboardHide();",
            completionHandler: nil
        )
    }
}

// MARK: - UITextViewDelegate

extension NativeInputOverlay: UITextViewDelegate {

    func textViewDidChange(_ textView: UITextView) {
        let text = textView.text ?? ""
        currentText = text
        placeholderLabel?.isHidden = !text.isEmpty
        onTextChange?(text)
        reflowHeight()
    }

    func textViewDidBeginEditing(_ textView: UITextView) {
        placeholderLabel?.isHidden = !(textView.text?.isEmpty ?? true)
    }

    func textViewDidEndEditing(_ textView: UITextView) {
        currentText = textView.text ?? ""
        onTextChange?(currentText)
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.08) { [weak self] in
            self?.dismissInternal(animated: true, syncText: false, fireCallback: true)
        }
    }

    func textView(_ textView: UITextView, shouldChangeTextIn range: NSRange, replacementText text: String) -> Bool {
        if text == "\n" {
            let trimmed = (textView.text ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
            if !trimmed.isEmpty {
                onSubmit?(textView.text ?? "")
            }
            return false
        }
        return true
    }
}







